//Galois Field Multiplication Macro
#define GMUL(a, b, p, d) ({ \
	unsigned int result = 0; \
	unsigned int temp_a = a; \
	unsigned int temp_b = b; \
	while (temp_b > 0) { \
		if (temp_b & 1) \
			result ^= temp_a; \
		temp_a <<= 1; \
		if (temp_a & (1 << d)) \
			temp_a ^= p; \
		temp_b >>= 1; \
	} \
	result & ((1 << d) - 1); \
})

//Matrix Macro 
#define MC(x0, x1, x2, x3, y0, y1, y2, y3)  { \
	y0 = GMUL(x0,2,0x1B,8) ^ GMUL(x1,3,0x1B,8) ^ x2 ^ x3; \
	y1 = x0 ^ GMUL(x1,2,0x1B,8) ^ GMUL(x2,3,0x1B,8) ^ x3; \
	y2 = x0 ^ x1 ^ GMUL(x2,2,0x1B,8) ^ GMUL(x3,3,0x1B,8); \
	y3 = GMUL(x0,3,0x1B,8) ^ x1 ^ x2 ^ GMUL(x3,2,0x1B,8); \
} 

